const item = $input.first().json;
const body = item.body || item;
const headers = item.headers || {};
const expected = "8973d464f5f1475b83d6ab88d222d824";

// Secret check from header or body
const incoming = body.secret || headers['x-n8n-internal-secret'] || headers['x-internal-secret'] || headers['x-n8n-auth-token'] || '';
const isScheduled = (!headers.host && !headers['content-type']) || !!item.timestamp;
const isAuthorized = isScheduled || (incoming === expected);

// Infer event_type
let eventType = String(body.event_type || '').toUpperCase();
if (!eventType) {
  if (isScheduled) eventType = 'HR_RECOVERY';
  else if (body.batch_id && (body.files || body.file_count)) eventType = 'HR_UPLOAD';
  else if (body.action_type === 'APPROVAL_CALLBACK' || body.approved_by || (body.staging_id && !body.sync_task_id && !body.task_id)) eventType = 'HR_APPROVAL';
  else if (body.sync_task_id || body.task_id || body.action_type === 'SEQUENTIAL_SYNC' || body.action_type === 'RETRY_SYNC') eventType = 'HR_RETRY_SYNC';
  else eventType = 'HR_UPLOAD';
}

return [{
  json: {
    isAuthorized,
    isScheduled,
    event_type: eventType,
    batch_id: body.batch_id || null,
    file_id: body.file_id || null,
    employee_id: body.employee_id || null,
    staging_id: body.staging_id || null,
    sync_task_id: body.sync_task_id || body.task_id || null,
    task_id: body.sync_task_id || body.task_id || null,
    company_id: body.company_id || 'STL',
    sync_version: body.sync_version || 1,
    idempotency_key: body.idempotency_key || ('idem_' + Date.now()),
    correlation_id: body.correlation_id || ('corr_' + Date.now()),
    created_at: body.created_at || new Date().toISOString(),
    raw_payload: body
  }
}];

const item = $input.first().json;
const payload = item.raw_payload || {};
return [{
  json: {
    success: true,
    event_type: 'HR_APPROVAL',
    status: 'recorded',
    staging_id: payload.staging_id || item.staging_id,
    employee_id: payload.employee_id || item.employee_id,
    company_id: payload.company_id || item.company_id,
    sync_version: payload.sync_version || item.sync_version || 1,
    approved_by: payload.approved_by || 'hr_admin',
    timestamp: new Date().toISOString()
  }
}];

const res = $input.first().json;
const tasks = res.tasks || [];
return [{
  json: {
    event_type: 'HR_RECOVERY',
    scanned_count: tasks.length,
    status: 'recovery_scan_completed',
    timestamp: new Date().toISOString(),
    tasks
  }
}];

const it = $input.first();
